message.content:
I'm restoring a Coral NPU project at /app. Create ALL of the following Chisel (Scala) bus module files. These implement the TileLink-UL and AXI bus infrastructure.

The project uses Chisel 5 / CIRCT. All files use Scala 2.13. The BUILD files already exist.

**Package**: `package bus`
**Imports**: `import chisel3._`, `import chisel3.util._`

## Key type definitions used throughout (define in TileLinkUL.scala):

```scala
// TileLink-UL parameters
case class TLULParameters(
  dataWidth: Int = 32,
  addrWidth: Int = 32,
  idWidth: Int = 4,
  sizeWidth: Int = 3,
  maskWidth: Int = 4,
  sourceWidth: Int = 4
)

// TileLink-UL channel A (request)
class TLChannelA(p: TLULParameters) extends Bundle {
  val opcode  = UInt(3.W)
  val param   = UInt(3.W)
  val size    = UInt(p.sizeWidth.W)
  val source  = UInt(p.sourceWidth.W)
  val address = UInt(p.addrWidth.W)
  val mask    = UInt(p.maskWidth.W)
  val data    = UInt(p.dataWidth.W)
  val corrupt = Bool()
}

// TileLink-UL channel D (response)
class TLChannelD(p: TLULParameters) extends Bundle {
  val opcode  = UInt(3.W)
  val param   = UInt(2.W)
  val size    = UInt(p.sizeWidth.W)
  val source  = UInt(p.sourceWidth.W)
  val sink    = UInt(1.W)
  val denied  = Bool()
  val data    = UInt(p.dataWidth.W)
  val corrupt = Bool()
}

class TLBundleUL(p: TLULParameters) extends Bundle {
  val a = Decoupled(new TLChannelA(p))
  val d = Flipped(Decoupled(new TLChannelD(p)))
}
```

### OpenTitanTileLink compatibility object:
```scala
object OpenTitanTileLink {
  class Host2Device(p: TLULParameters) extends TLBundleUL(p)
}
```

### TLULOpcodesA:
```scala
object TLULOpcodesA {
  val Get         = 4.U(3.W)
  val PutFullData = 0.U(3.W)
  val PutPartData = 1.U(3.W)
}
object TLULOpcodesD {
  val AccessAck     = 0.U(3.W)
  val AccessAckData = 1.U(3.W)
}
```

## AXI bundle (define in Axi.scala):

These signal names MUST match exactly what the testbench expects:
- `io_axi_slave_read_addr_valid/ready/bits_id/bits_addr/bits_len/bits_size/bits_burst`
- `io_axi_master_read_addr_valid/ready/bits_id/bits_addr/bits_size/bits_len/bits_burst`
- etc.

So the bundle MUST be named with these field names:

```scala
package bus
import chisel3._
import chisel3.util._

class AxiReadAddrBits(addrBits: Int, idBits: Int) extends Bundle {
  val id    = UInt(idBits.W)
  val addr  = UInt(addrBits.W)
  val len   = UInt(8.W)
  val size  = UInt(3.W)
  val burst = UInt(2.W)
}
class AxiReadDataBits(dataBits: Int, idBits: Int) extends Bundle {
  val id   = UInt(idBits.W)
  val data = UInt(dataBits.W)
  val resp = UInt(2.W)
  val last = Bool()
}
class AxiWriteAddrBits(addrBits: Int, idBits: Int) extends Bundle {
  val id    = UInt(idBits.W)
  val addr  = UInt(addrBits.W)
  val len   = UInt(8.W)
  val size  = UInt(3.W)
  val burst = UInt(2.W)
}
class AxiWriteDataBits(dataBits: Int) extends Bundle {
  val data = UInt(dataBits.W)
  val strb = UInt((dataBits/8).W)
  val last = Bool()
}
class AxiWriteRespBits(idBits: Int) extends Bundle {
  val id   = UInt(idBits.W)
  val resp = UInt(2.W)
}

// From DUT perspective as AXI MASTER:
// read.addr is OUTPUT (DUT sends requests)
// read.data is INPUT (DUT receives data)
// write.addr is OUTPUT
// write.data is OUTPUT
// write.resp is INPUT
class AxiBundle(dataBits: Int, addrBits: Int, idBits: Int) extends Bundle {
  val read = new Bundle {
    val addr = Decoupled(new AxiReadAddrBits(addrBits, idBits))
    val data = Flipped(Decoupled(new AxiReadDataBits(dataBits, idBits)))
  }
  val write = new Bundle {
    val addr = Decoupled(new AxiWriteAddrBits(addrBits, idBits))
    val data = Decoupled(new AxiWriteDataBits(dataBits))
    val resp = Flipped(Decoupled(new AxiWriteRespBits(idBits)))
  }
}

// AxiMasterIO - named differently for peripherals
class AxiMasterIO(addrBits: Int, dataBits: Int, idBits: Int) extends Bundle {
  val read = new Bundle {
    val addr = Decoupled(new AxiReadAddrBits(addrBits, idBits))
    val data = Flipped(Decoupled(new AxiReadDataBits(dataBits, idBits)))
  }
  val write = new Bundle {
    val addr = Decoupled(new AxiWriteAddrBits(addrBits, idBits))
    val data = Decoupled(new AxiWriteDataBits(dataBits))
    val resp = Flipped(Decoupled(new AxiWriteRespBits(idBits)))
  }
}
```

Now create each file:

## `/app/hdl/chisel/src/bus/TileLinkUL.scala`
Contains: TLULParameters, TLChannelA, TLChannelD, TLBundleUL, OpenTitanTileLink, TLULOpcodesA, TLULOpcodesD, TLULOpcodesParam, SecdedEncoder class, TlulIntegrityModules.

SecdedEncoder(width):
- Takes data input, produces ECC output (7 bits for 32-bit data)
- `val io = IO(new Bundle { val data_i = Input(UInt(width.W)); val ecc_o = Output(UInt(7.W)) })`
- Compute Hamming SEC-DED code

```scala
package bus

import chisel3._
import chisel3.util._

case class TLULParameters(
  dataWidth:   Int = 32,
  addrWidth:   Int = 32,
  idWidth:     Int = 4,
  sizeWidth:   Int = 3,
  maskWidth:   Int = 4,
  sourceWidth: Int = 4
)

object TLULParameters {
  def apply(p: Any): TLULParameters = TLULParameters()
}

class TLChannelA(p: TLULParameters) extends Bundle {
  val opcode  = UInt(3.W)
  val param   = UInt(3.W)
  val size    = UInt(p.sizeWidth.W)
  val source  = UInt(p.sourceWidth.W)
  val address = UInt(p.addrWidth.W)
  val mask    = UInt(p.maskWidth.W)
  val data    = UInt(p.dataWidth.W)
  val corrupt = Bool()
}

class TLChannelD(p: TLULParameters) extends Bundle {
  val opcode  = UInt(3.W)
  val param   = UInt(2.W)
  val size    = UInt(p.sizeWidth.W)
  val source  = UInt(p.sourceWidth.W)
  val sink    = UInt(1.W)
  val denied  = Bool()
  val data    = UInt(p.dataWidth.W)
  val corrupt = Bool()
}

class TLBundleUL(p: TLULParameters) extends Bundle {
  val a = Decoupled(new TLChannelA(p))
  val d = Flipped(Decoupled(new TLChannelD(p)))
}

object OpenTitanTileLink {
  class Host2Device(p: TLULParameters) extends TLBundleUL(p)
  class A_Channel(p: TLULParameters) extends TLChannelA(p)
  class D_Channel(p: TLULParameters) extends TLChannelD(p)
}

object TLULOpcodesA {
  val Get         = 4.U(3.W)
  val PutFullData = 0.U(3.W)
  val PutPartData = 1.U(3.W)
}

object TLULOpcodesD {
  val AccessAck     = 0.U(3.W)
  val AccessAckData = 1.U(3.W)
}

class SecdedEncoder(width: Int) extends Module {
  val io = IO(new Bundle {
    val data_i = Input(UInt(width.W))
    val ecc_o  = Output(UInt(7.W))
  })
  // Simple parity for now
  io.ecc_o := 0.U
}

// Integrity generation/checking stubs
class RequestIntegrityGen(p: TLULParameters) extends Module {
  val io = IO(new Bundle {
    val tl_i = Input(new TLBundleUL(p))
    val tl_o = Output(new TLBundleUL(p))
  })
  io.tl_o := io.tl_i
}

class RequestIntegrityCheck(p: TLULParameters) extends Module {
  val io = IO(new Bundle {
    val tl_i = Input(new TLBundleUL(p))
    val tl_o = Output(new TLBundleUL(p))
    val err  = Output(Bool())
  })
  io.tl_o := io.tl_i
  io.err := false.B
}

class ResponseIntegrityGen(p: TLULParameters) extends Module {
  val io = IO(new Bundle {
    val tl_i = Input(new TLBundleUL(p))
    val tl_o = Output(new TLBundleUL(p))
  })
  io.tl_o := io.tl_i
}

class ResponseIntegrityCheck(p: TLULParameters) extends Module {
  val io = IO(new Bundle {
    val tl_i = Input(new TLBundleUL(p))
    val tl_o = Output(new TLBundleUL(p))
    val err  = Output(Bool())
  })
  io.tl_o := io.tl_i
  io.err := false.B
}
```

