## `/app/hdl/chisel/src/bus/TlulToSram.scala`
TileLink-UL to SRAM adapter:
```scala
class TlulToSramSramIO(addrBits: Int, dataWidth: Int) extends Bundle {
  val enable = Output(Bool())
  val write  = Output(Bool())
  val addr   = Output(UInt(addrBits.W))
  val wdata  = Output(UInt(dataWidth.W))
  val wmask  = Output(UInt((dataWidth/8).W))
  val rvalid = Input(Bool())
  val rdata  = Input(UInt(dataWidth.W))
}

class TlulToSram(p: TLULParameters, addrBits: Int) extends Module {
  val io = IO(new Bundle {
    val tl   = Flipped(new TLBundleUL(p))
    val sram = new TlulToSramSramIO(addrBits, p.dataWidth)
  })
  // Simple: accept request, pass to SRAM, return response
  val req = io.tl.a
  val resp = io.tl.d

  io.sram.enable := req.valid
  io.sram.write  := req.bits.opcode =/= TLULOpcodesA.Get
  io.sram.addr   := req.bits.address(addrBits-1, 0)
  io.sram.wdata  := req.bits.data
  io.sram.wmask  := req.bits.mask

  req.ready := true.B

  val respValid = RegInit(false.B)
  val respData  = RegInit(0.U(p.dataWidth.W))
  val respSrc   = RegInit(0.U(p.sourceWidth.W))
  val respOp    = RegInit(0.U(3.W))
  val respSz    = RegInit(0.U(p.sizeWidth.W))

  when(req.fire) {
    respValid := true.B
    respSrc := req.bits.source
    respOp  := Mux(req.bits.opcode === TLULOpcodesA.Get, TLULOpcodesD.AccessAckData, TLULOpcodesD.AccessAck)
    respSz  := req.bits.size
  }
  when(io.sram.rvalid) { respData := io.sram.rdata }
  when(resp.fire) { respValid := false.B }

  resp.valid := respValid
  resp.bits.opcode  := respOp
  resp.bits.param   := 0.U
  resp.bits.size    := respSz
  resp.bits.source  := respSrc
  resp.bits.sink    := 0.U
  resp.bits.denied  := false.B
  resp.bits.data    := respData
  resp.bits.corrupt := false.B
}
```

