## `/app/hdl/chisel/src/bus/TlulSocket1N.scala`
1-to-N TL-UL socket (route by address):
```scala
package bus
import chisel3._
import chisel3.util._

class TlulSocket1N(p: TLULParameters, n: Int, addrBits: Int = 32) extends Module {
  val io = IO(new Bundle {
    val tl_h = Flipped(new TLBundleUL(p))
    val tl_d = Vec(n, new TLBundleUL(p))
    val devSel = Input(Vec(n, Bool()))
  })
  // Route to selected device
  val sel = PriorityEncoder(io.devSel)
  for (i <- 0 until n) {
    io.tl_d(i).a.valid := io.tl_h.a.valid && io.devSel(i)
    io.tl_d(i).a.bits  := io.tl_h.a.bits
    io.tl_d(i).d.ready := io.tl_h.d.ready && io.devSel(i)
  }
  io.tl_h.a.ready := io.tl_d(sel).a.ready
  io.tl_h.d.valid := io.tl_d(sel).d.valid
  io.tl_h.d.bits  := io.tl_d(sel).d.bits
}

class TlulSocket1N_128Emitter extends App {}
```

## `/app/hdl/chisel/src/bus/TlulSocketM1.scala`
M-to-1 TL-UL socket:
```scala
package bus
import chisel3._
import chisel3.util._

class TlulSocketM1(p: TLULParameters, m: Int) extends Module {
  val io = IO(new Bundle {
    val tl_h = Vec(m, Flipped(new TLBundleUL(p)))
    val tl_d = new TLBundleUL(p)
  })
  // Round-robin arbitration
  val arb = Module(new RRArbiter(new TLChannelA(p), m))
  for (i <- 0 until m) {
    arb.io.in(i) <> io.tl_h(i).a
  }
  io.tl_d.a <> arb.io.out
  // Demux D channel back
  val srcReg = RegInit(0.U(log2Ceil(m).W))
  when(io.tl_d.a.fire) { srcReg := arb.io.chosen }
  for (i <- 0 until m) {
    io.tl_h(i).d.valid := io.tl_d.d.valid && srcReg === i.U
    io.tl_h(i).d.bits  := io.tl_d.d.bits
  }
  io.tl_d.d.ready := io.tl_h(srcReg).d.ready
}

class TlulSocketM1_2_128Emitter extends App {}
class TlulSocketM1_3_128Emitter extends App {}
```

