## `/app/hdl/chisel/src/bus/Clint.scala`
RISC-V CLINT (Core Local Interruptor):
```scala
package bus
import chisel3._
import chisel3.util._

class Clint(p: TLULParameters) extends Module {
  val io = IO(new Bundle {
    val tl        = Flipped(new TLBundleUL(p))
    val timer_irq = Output(Bool())
    val sw_irq    = Output(Bool())
  })
  val mtime    = RegInit(0.U(64.W))
  val mtimecmp = RegInit(~0.U(64.W))
  val msip     = RegInit(false.B)
  mtime := mtime + 1.U
  io.timer_irq := mtime >= mtimecmp
  io.sw_irq := msip
  // TLUL interface (simplified)
  io.tl.a.ready := true.B
  io.tl.d.valid := RegNext(io.tl.a.fire)
  io.tl.d.bits := 0.U.asTypeOf(new TLChannelD(p))
  when(io.tl.a.fire) {
    when(io.tl.a.bits.opcode === TLULOpcodesA.PutFullData) {
      when(io.tl.a.bits.address(3) === 0.U && io.tl.a.bits.address(15, 4) === 0.U) {
        msip := io.tl.a.bits.data(0)
      }
    }
  }
}
```

## `/app/hdl/chisel/src/bus/Plic.scala`
RISC-V PLIC (Platform Level Interrupt Controller):
```scala
package bus
import chisel3._
import chisel3.util._

class Plic(p: TLULParameters, nSources: Int = 32) extends Module {
  val io = IO(new Bundle {
    val tl       = Flipped(new TLBundleUL(p))
    val irqs     = Input(UInt(nSources.W))
    val irqOut   = Output(Bool())
  })
  val pending  = RegInit(0.U(nSources.W))
  val enable   = RegInit(0.U(nSources.W))
  val priority = RegInit(VecInit(Seq.fill(nSources)(0.U(3.W))))
  val threshold = RegInit(0.U(3.W))
  pending := pending | io.irqs
  io.irqOut := (pending & enable).orR
  io.tl.a.ready := true.B
  io.tl.d.valid := RegNext(io.tl.a.fire)
  io.tl.d.bits := 0.U.asTypeOf(new TLChannelD(p))
}
```

## `/app/hdl/chisel/src/bus/GPIO.scala`
```scala
package bus
import chisel3._
import chisel3.util._

case class GPIOParameters(width: Int = 8)

class GPIO(p: TLULParameters, gp: GPIOParameters) extends Module {
  val io = IO(new Bundle {
    val tl       = Flipped(new TLBundleUL(p))
    val gpio_o   = Output(UInt(gp.width.W))
    val gpio_en_o = Output(UInt(gp.width.W))
    val gpio_i   = Input(UInt(gp.width.W))
  })
  // Registers: 0x00=DATA_IN, 0x04=DATA_OUT, 0x08=OUT_EN
  val dataOut = RegInit(0.U(gp.width.W))
  val outEn   = RegInit(0.U(gp.width.W))
  io.gpio_o    := dataOut
  io.gpio_en_o := outEn
  io.tl.a.ready := true.B
  val respValid = RegInit(false.B)
  val respData  = RegInit(0.U(p.dataWidth.W))
  val respSrc   = RegInit(0.U(p.sourceWidth.W))
  val respOp    = RegInit(TLULOpcodesD.AccessAck)
  when(io.tl.a.fire) {
    respValid := true.B
    respSrc := io.tl.a.bits.source
    val addr = io.tl.a.bits.address(7, 0)
    when(io.tl.a.bits.opcode =/= TLULOpcodesA.Get) {
      when(addr === 0x04.U) { dataOut := io.tl.a.bits.data(gp.width-1, 0) }
      when(addr === 0x08.U) { outEn   := io.tl.a.bits.data(gp.width-1, 0) }
      respOp := TLULOpcodesD.AccessAck
    } .otherwise {
      respOp := TLULOpcodesD.AccessAckData
      respData := MuxLookup(addr, 0.U)(Seq(
        0x00.U -> io.gpio_i,
        0x04.U -> dataOut,
        0x08.U -> outEn
      ))
    }
  }
  when(io.tl.d.fire) { respValid := false.B }
  io.tl.d.valid := respValid
  io.tl.d.bits.opcode := respOp
  io.tl.d.bits.param  := 0.U
  io.tl.d.bits.size   := 2.U
  io.tl.d.bits.source := respSrc
  io.tl.d.bits.sink   := 0.U
  io.tl.d.bits.denied := false.B
  io.tl.d.bits.data   := respData
  io.tl.d.bits.corrupt := false.B
}
```

## `/app/hdl/chisel/src/bus/SpiMaster.scala`
```scala
package bus
import chisel3._
import chisel3.util._

case class SpiMasterParameters(dataWidth: Int = 8)

class SpiIO extends Bundle {
  val mosi = Output(Bool())
  val miso = Input(Bool())
  val sclk = Output(Bool())
  val csb  = Output(UInt(1.W))  // chip select (active low)
}

class SpiMasterCtrl(p: TLULParameters) extends Module {
  val io = IO(new Bundle {
    val tl  = Flipped(new TLBundleUL(p))
    val spi = new SpiIO
  })
  // Registers: STATUS(0), CTRL(4), TXDATA(8), RXDATA(c), CSID(10), CSMODE(14)
  val ctrl   = RegInit(0.U(32.W))
  val txData = RegInit(0.U(8.W))
  val rxData = RegInit(0.U(8.W))
  val status = RegInit(0.U(32.W))
  io.spi.mosi := txData(7)
  io.spi.sclk := false.B
  io.spi.csb  := 1.U
  io.tl.a.ready := true.B
  val respValid = RegInit(false.B)
  val respData  = RegInit(0.U(32.W))
  val respSrc   = RegInit(0.U(p.sourceWidth.W))
  when(io.tl.a.fire) {
    respValid := true.B
    respSrc := io.tl.a.bits.source
    when(io.tl.a.bits.opcode =/= TLULOpcodesA.Get) {
      val addr = io.tl.a.bits.address(7, 0)
      when(addr === 0x04.U) { ctrl   := io.tl.a.bits.data }
      when(addr === 0x08.U) { txData := io.tl.a.bits.data(7, 0) }
    } .otherwise {
      val addr = io.tl.a.bits.address(7, 0)
      respData := MuxLookup(addr, 0.U)(Seq(
        0x00.U -> status, 0x04.U -> ctrl, 0x0C.U -> rxData
      ))
    }
  }
  when(io.tl.d.fire) { respValid := false.B }
  io.tl.d.valid := respValid
  io.tl.d.bits := 0.U.asTypeOf(new TLChannelD(p))
  io.tl.d.bits.source := respSrc
  io.tl.d.bits.data := respData
}

class SpiMaster(p: TLULParameters) extends Module {
  val io = IO(new Bundle {
    val clk_i   = Input(Clock())
    val rst_ni  = Input(Bool())
    val spi_clk_i = Input(Clock())
    val tl      = Flipped(new TLBundleUL(p))
    val spi     = new SpiIO
  })
  val ctrl = Module(new SpiMasterCtrl(p))
  ctrl.io.tl <> io.tl
  ctrl.io.spi <> io.spi
}
