package bus
import chisel3._
import chisel3.util._

class Axi2TLUL(axiP: bus.AxiBundle, tlP: TLULParameters) extends Module {
  val io = IO(new Bundle {
    val axi = Flipped(new bus.AxiBundle(axiP.read.data.bits.data.getWidth, 32, 4))
    val tl  = new TLBundleUL(tlP)
  })
  // Read: AXI AR → TL A (Get), TL D → AXI R
  io.tl.a.valid := io.axi.read.addr.valid || io.axi.write.addr.valid
  io.tl.a.bits.opcode := Mux(io.axi.read.addr.valid, TLULOpcodesA.Get, TLULOpcodesA.PutFullData)
  io.tl.a.bits.param := 0.U
  io.tl.a.bits.size := 2.U
  io.tl.a.bits.source := 0.U
  io.tl.a.bits.address := Mux(io.axi.read.addr.valid, io.axi.read.addr.bits.addr, io.axi.write.addr.bits.addr)
  io.tl.a.bits.mask := 0xF.U
  io.tl.a.bits.data := io.axi.write.data.bits.data(31, 0)
  io.tl.a.bits.corrupt := false.B
  io.axi.read.addr.ready := io.tl.a.ready
  io.axi.write.addr.ready := io.tl.a.ready && !io.axi.read.addr.valid
  io.axi.write.data.ready := true.B
  // Response
  io.axi.read.data.valid := io.tl.d.valid && io.tl.d.bits.opcode === TLULOpcodesD.AccessAckData
  io.axi.read.data.bits.id := 0.U
  io.axi.read.data.bits.data := io.tl.d.bits.data
  io.axi.read.data.bits.resp := 0.U
  io.axi.read.data.bits.last := true.B
  io.axi.write.resp.valid := io.tl.d.valid && io.tl.d.bits.opcode === TLULOpcodesD.AccessAck
  io.axi.write.resp.bits.id := 0.U
  io.axi.write.resp.bits.resp := 0.U
  io.tl.d.ready := io.axi.read.data.ready || io.axi.write.resp.ready
}

class EmitAxi2TLUL extends App {}
