// ---------------------------------------------------------------------------
// Extended D-channel bundle for Spi2TLULV2
//
// The V2 bridge uses an extended TL-D encoding that includes explicit user
// and error fields on top of the standard TLChannelD fields.
// ---------------------------------------------------------------------------

class Spi2TLULV2_D_Channel(p: TLULParameters) extends Bundle {
  val opcode  = UInt(3.W)
  val param   = UInt(3.W)
  val size    = UInt(p.sizeWidth.W)
  val source  = UInt(p.sourceWidth.W)
  val sink    = UInt(1.W)
  val data    = UInt(p.dataWidth.W)
  val user    = new OpenTitanTileLink_D_User
  val error   = UInt(1.W)
}

/** SPI-to-TL-UL bridge (v2).
  *
  * Converts SPI transactions into TL-UL requests using an async SPI clock
  * domain.  The SPI frame format is:
  *   Byte 0       : opcode (0x01 = read, 0x02 = write)
  *   Bytes 1-4    : address (big-endian)
  *   Bytes 5-6    : number of 128-bit beats minus 1 (big-endian)
  *   Bytes 7-…   : write payload (for write frames)
  *
  * MISO: for read frames the module streams back TL-D response data prefixed
  * by a 0xFE sync byte per beat.
  *
  * The queued IO ports (`q_mosi_pin`, `q_miso_pin`, `q_tl_a`, `q_tl_d`)
  * decouple the SPI clock domain from the system clock domain.
  *
  * @param p coralnpu system parameters
  */
class Spi2TLULV2(p: coralnpu.Parameters) extends Module {
  private val tlP = TLULParameters(p)

  val io = IO(new Bundle {
    // SPI physical clock / reset (async to system clock)
    val spi_clk   = Input(Clock())
    val spi_rst_n = Input(Bool())

    // Queued MOSI / MISO bit streams (system clock domain)
    val q_mosi_pin = Flipped(Decoupled(Bool()))
    val q_miso_pin = Decoupled(Bool())

    // Queued TL-UL channels (system clock domain)
    val q_tl_a = Decoupled(new TLChannelA(tlP))
    val q_tl_d = Flipped(Decoupled(new Spi2TLULV2_D_Channel(tlP)))
  })

  // -------------------------------------------------------------------------
  // SPI bit receiver (system clock domain model)
  //
  // In a real implementation the SPI clock domain would be used here.
  // For simulation / single-clock-domain purposes we model the SPI receiver
  // as a simple state machine that detects the spi_rst_n / spi_clk edges
  // through the Boolean input.
  //
  // Protocol state machine:
  //   Header: opcode(1B) + addr(4B) + len(2B) = 7 bytes = 56 bits
  //   Data  : nBeats × 16 bytes × 8 bits/byte
  //
  // The SPI clock is exposed as a Bool (toggles in simulation).  We detect
  // posedges of spi_clk by comparing current and previous values.
  // -------------------------------------------------------------------------

  // Shadow spi_clk as a Bool for edge detection in the system domain.
  val spiClkBool = io.spi_clk.asUInt.asBool  // value of SPI clock in sys domain
  val spiClkPrev = RegNext(spiClkBool, false.B)
  val spiPosedge = spiClkBool && !spiClkPrev

  // Active when spi_rst_n is asserted (frame in progress, CSB low).
  val active = io.spi_rst_n

  // -------------------------------------------------------------------------
  // Receiver state
  // -------------------------------------------------------------------------
  // We accumulate bits MSB-first into a wide shift register.
  // Header = 56 bits.
  val HEADER_BITS  = 56
  val BEAT_BITS    = 128
  val BEAT_BYTES   = BEAT_BITS / 8

  val sState_header :: sState_data :: sState_respond :: Nil = Enum(3)
  val recvState = RegInit(sState_header)

  val sreg     = RegInit(0.U(HEADER_BITS.W)) // shift register for header
  val bitIdx   = RegInit(0.U(7.W))           // bit count within current phase

  // Decoded header fields (latched after 56 bits).
  val hdrOpcode = RegInit(0.U(8.W))  // 0x01=read, 0x02=write
  val hdrAddr   = RegInit(0.U(32.W))
  val hdrLen    = RegInit(0.U(16.W)) // number of beats minus 1

  // Data accumulator for write frames.
  val dataSreg   = RegInit(0.U(BEAT_BITS.W))
  val dataBitIdx = RegInit(0.U(8.W))
  val beatIdx    = RegInit(0.U(16.W))

  // -------------------------------------------------------------------------
  // MISO transmit state
  // -------------------------------------------------------------------------
  val misoBuf     = RegInit(0.U(9.W))  // 1 sync-bit (0xFE prefix) + 8 data bits
  val misoBitIdx  = RegInit(0.U(8.W))
  val misoBeats   = RegInit(0.U(16.W))
  val misoBeatIdx = RegInit(0.U(16.W))
  val misoData    = RegInit(0.U(BEAT_BITS.W))
  val misoActive  = RegInit(false.B)
  // 0xFE sync byte + 16 bytes per beat
  val MISO_BITS_PER_BEAT = 8 + BEAT_BITS // sync byte + data

  // TL-A output queue
  val tlAValid = RegInit(false.B)
  val tlABits  = RegInit(0.U.asTypeOf(new TLChannelA(tlP)))

  // -------------------------------------------------------------------------
  // Reset when CSB deasserted
  // -------------------------------------------------------------------------
  when(!active) {
    recvState  := sState_header
    bitIdx     := 0.U
    dataBitIdx := 0.U
    beatIdx    := 0.U
    sreg       := 0.U
    dataSreg   := 0.U
    misoActive := false.B
  }

  // -------------------------------------------------------------------------
  // SPI bit receive on posedge
  // -------------------------------------------------------------------------
  when(active && spiPosedge) {
    val bit = io.q_mosi_pin.bits

    switch(recvState) {
      is(sState_header) {
        sreg   := Cat(sreg(HEADER_BITS - 2, 0), bit)
        bitIdx := bitIdx + 1.U
        when(bitIdx === (HEADER_BITS - 1).U) {
          // Latch header.
          val fullSreg = Cat(sreg(HEADER_BITS - 2, 0), bit)
          hdrOpcode := fullSreg(55, 48)
          hdrAddr   := fullSreg(47, 16)
          hdrLen    := fullSreg(15, 0)
          bitIdx    := 0.U
          dataBitIdx := 0.U
          beatIdx    := 0.U
          dataSreg   := 0.U
          // For reads, immediately start generating TL-A.
          when(fullSreg(55, 48) === 0x01.U) {
            // Kick off first read request.
            tlAValid       := true.B
            tlABits.opcode  := TLULOpcodesA.Get
            tlABits.param   := 0.U
            tlABits.size    := 4.U  // 16 bytes
            tlABits.source  := 0.U
            tlABits.address := fullSreg(47, 16)
            tlABits.mask    := ~0.U(tlP.maskWidth.W)
            tlABits.data    := 0.U
            tlABits.corrupt := false.B
            recvState := sState_respond
          } .otherwise {
            recvState := sState_data
          }
        }
      }

      is(sState_data) {
        dataSreg   := Cat(dataSreg(BEAT_BITS - 2, 0), bit)
        dataBitIdx := dataBitIdx + 1.U
        when(dataBitIdx === (BEAT_BITS - 1).U) {
          // Full beat received: emit TL-A write.
          val fullData = Cat(dataSreg(BEAT_BITS - 2, 0), bit)
          tlAValid       := true.B
          tlABits.opcode  := TLULOpcodesA.PutFullData
          tlABits.param   := 0.U
          tlABits.size    := 4.U
          tlABits.source  := 0.U
          tlABits.address := hdrAddr + (beatIdx << 4)
          tlABits.mask    := ~0.U(tlP.maskWidth.W)
          // Reverse byte order: SPI sends big-endian, TL-UL expects little-endian.
          val beBytes = Wire(Vec(BEAT_BYTES, UInt(8.W)))
          for (i <- 0 until BEAT_BYTES) {
            beBytes(i) := fullData(BEAT_BITS - 1 - i * 8, BEAT_BITS - 8 - i * 8)
          }
          tlABits.data    := Cat(beBytes.reverse)
          tlABits.corrupt := false.B

          dataBitIdx := 0.U
          dataSreg   := 0.U
          beatIdx    := beatIdx + 1.U
          // Stay in data state if more beats remain.
        }
      }

      is(sState_respond) {
        // In read mode we don't process MOSI.
        // Advance MISO shift out.
      }
    }
  }

  // -------------------------------------------------------------------------
  // TL-A output
  // -------------------------------------------------------------------------
  io.q_tl_a.valid := tlAValid
  io.q_tl_a.bits  := tlABits
  when(io.q_tl_a.fire) {
    tlAValid := false.B
  }

  // -------------------------------------------------------------------------
  // TL-D input → MISO output (read path)
  // -------------------------------------------------------------------------
  // When a D response arrives, buffer it and shift it out on MISO.
  val pendingResponse = RegInit(false.B)
  val pendingData     = RegInit(0.U(BEAT_BITS.W))
  val pendingBits     = RegInit(0.U(8.W)) // remaining bits to send (incl sync byte)
  val syncSent        = RegInit(false.B)

  io.q_tl_d.ready := !pendingResponse

  when(io.q_tl_d.fire) {
    pendingResponse := true.B
    // Data arrives in little-endian; reverse to big-endian for MISO.
    val d = io.q_tl_d.bits.data
    val bVec = Wire(Vec(BEAT_BYTES, UInt(8.W)))
    for (i <- 0 until BEAT_BYTES) bVec(i) := d(i * 8 + 7, i * 8)
    pendingData := Cat(bVec.reverse)
    pendingBits := (8 + BEAT_BITS).U  // sync byte + data bits
    syncSent    := false.B
  }

  // MISO valid when there are pending bits.
  io.q_miso_pin.valid := pendingResponse
  // Shift out MSB first.  First 8 bits are the 0xFE sync byte.
  val syncByte   = 0xfe.U(8.W)
  val totalBits  = 8 + BEAT_BITS
  val bitsLeft   = RegInit(0.U(9.W))

  // We re-use pendingBits as bitsLeft.
  when(io.q_tl_d.fire) {
    bitsLeft := totalBits.U
  }

  val misoShiftReg = RegInit(Cat(0xfe.U(8.W), 0.U(BEAT_BITS.W)))

  when(io.q_tl_d.fire) {
    val d = io.q_tl_d.bits.data
    val bVec2 = Wire(Vec(BEAT_BYTES, UInt(8.W)))
    for (i <- 0 until BEAT_BYTES) bVec2(i) := d(i * 8 + 7, i * 8)
    misoShiftReg := Cat(0xfe.U(8.W), Cat(bVec2.reverse))
    bitsLeft := (8 + BEAT_BITS).U
    pendingResponse := true.B
  }

  io.q_miso_pin.bits := misoShiftReg(8 + BEAT_BITS - 1)

  when(io.q_miso_pin.fire) {
    misoShiftReg := Cat(misoShiftReg(8 + BEAT_BITS - 2, 0), false.B)
    bitsLeft     := bitsLeft - 1.U
    when(bitsLeft <= 1.U) {
      pendingResponse := false.B
      // Trigger next read beat if more beats remain.
      when(hdrOpcode === 0x01.U && misoBeatIdx < hdrLen) {
        misoBeatIdx := misoBeatIdx + 1.U
        tlAValid       := true.B
        tlABits.opcode  := TLULOpcodesA.Get
        tlABits.param   := 0.U
        tlABits.size    := 4.U
        tlABits.source  := 0.U
        tlABits.address := hdrAddr + ((misoBeatIdx + 1.U) << 4)
        tlABits.mask    := ~0.U(tlP.maskWidth.W)
        tlABits.data    := 0.U
        tlABits.corrupt := false.B
      }
    }
  }

  // MOSI consumption (always ready when active).
  io.q_mosi_pin.ready := active
}

