/** TileLink-UL bus parameters. */
case class TLULParameters(
  dataWidth:   Int = 32,
  addrWidth:   Int = 32,
  idWidth:     Int = 4,
  sizeWidth:   Int = 3,
  maskWidth:   Int = 4,
  sourceWidth: Int = 4
)

object TLULParameters {
  /** Construct from a coralnpu.Parameters instance.
    * The LSU data width drives the TL-UL data / mask widths.
    */
  def apply(p: coralnpu.Parameters): TLULParameters = {
    val dataBits = p.lsuDataBits
    val maskBits = dataBits / 8
    // sizeWidth must hold log2(maskBits+1) to encode all legal transfer sizes.
    val sizeW = math.ceil(math.log(maskBits + 1) / math.log(2)).toInt
    TLULParameters(
      dataWidth   = dataBits,
      addrWidth   = p.addrBits,
      idWidth     = p.axiIdBits,
      sizeWidth   = math.max(sizeW, 3),
      maskWidth   = maskBits,
      sourceWidth = p.tlulSourceWidth
    )
  }
}

